import numpy as np
from scipy.optimize import least_squares
def nmse(p,f):
    r=f(p)-sigma
    return np.mean(r**2)/np.var(sigma)
models={
 'A': lambda p: p[0]*eps**(p[1]+p[2]/T)*T**p[3]*np.exp(p[4]*eps) + p[5]*eps,
 'B': lambda p: p[0]*eps**p[1]*np.exp(p[2]*eps/T)*T**p[3] + p[4]*eps*np.exp(p[5]*T),
 'C': lambda p: p[0]*eps*np.exp(p[1]/T)*(1+p[2]*eps**p[3])*T**p[4],
 'D': lambda p: p[0]*eps**(p[1]+p[2]/T)*np.exp(p[3]*eps/T)+p[4]*eps*np.exp(p[5]/T),
}
rng=np.random.default_rng(0)
for k,f in models.items():
    best=(9,None)
    for _ in range(60):
        p0=rng.normal(0,1,6)
        try:
            s=least_squares(lambda p: f(p)-sigma, p0, max_nfev=2000)
            v=nmse(s.x,f)
            if v<best[0]: best=(v,s.x)
